What does this print?

```python
D = {("S","d"):"I", ("I","d"):"I",
     ("I","."):"P", ("P","d"):"F",
     ("F","d"):"F"}

def run(w):
    q = "S"
    for c in w:
        digit = c in "0123456789"
        if not digit and c != ".":
            return False
        k = "d" if digit else c
        q = D.get((q, k))
        if q is None:
            return False
    return q in {"I", "F"}

print([run(w) for w in
       ["0", "0.0", "00.", "1.23"]])
